package org.apache.commons.math.analysis;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.MaxIterationsExceededException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BrentSolver_solve_TriageGen2Test {

    /**
     * Mocking the function to control return values for different branches.
     */
    private interface MockFunction extends UnivariateRealFunction {
        double value(double x);
    }

    @Test
    public void testSolve_SignIsNegative_Success() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign < 0 (Bracketing works)
        // f(x) = x - 0.5. Root is 0.5.
        MockFunction f = mock(MockFunction.class);
        when(f.value(-1.0)).thenReturn(-1.5);
        when(f.value(1.0)).thenReturn(0.5);

        // We need to simulate the internal solve(min, yMin, max, yMax, min, yMin)
        // Since we can't easily mock the private recursive call of the real BrentSolver, 
        // we use a real function that satisfies the bracketing condition.
        BrentSolver solver = new BrentSolver(x -> x - 0.5);
        double result = solver.solve(-1.0, 1.0);
        assertEquals(0.5, result, 1e-10);
    }

    @Test
    public void testSolve_SignIsZero_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign == 0, yMin == 0.0
        BrentSolver solver = new BrentSolver(x -> x);
        double result = solver.solve(0.0, 1.0);
        assertEquals(0.0, result, 1e-10);
    }

    @Test
    public void testSolve_SignIsZero_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign == 0, yMax == 0.0
        BrentSolver solver = new BrentSolver(x -> x - 1.0);
        double result = solver.solve(0.0, 1.0);
        assertEquals(1.0, result, 1e-10);
    }

    @Test
    public void testSolve_SignIsPositive_MinIsCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign > 0 and Math.abs(yMin) <= functionValueAccuracy
        // Assuming default accuracy is small, e.g., 1e-14
        // We use a function where f(min) is exactly 0 or very small
        BrentSolver solver = new BrentSolver(x -> x + 1e-15); 
        // Note: BrentSolver's internal functionValueAccuracy is usually 1e-14
        double result = solver.solve(-1e-15, 1.0);
        // Depending on exact accuracy implementation, this should hit the if (Math.abs(yMin) <= functionValueAccuracy)
        assertTrue(Math.abs(result - (-1e-15)) < 1e-10);
    }

    @Test
    public void testSolve_SignIsPositive_MaxIsCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign > 0 and Math.abs(yMax) == functionValueAccuracy
        // This is a very specific branch. Since accuracy is private, we aim for a function 
        // where sign > 0 but max is a root.
        BrentSolver solver = new BrentSolver(x -> x);
        // We can't easily force the == accuracy check without knowing the exact constant, 
        // but we test the logic flow.
        try {
            solver.solve(1.0, 2.0);
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Function values at endpoints do not have different signs"));
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_SignIsPositive_ThrowsException() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: sign > 0 and neither is close to zero
        BrentSolver solver = new BrentSolver(x -> x + 10); 
        solver.solve(1.0, 2.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidInterval() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: verifyInterval(min, max) throws if min >= max
        BrentSolver solver = new BrentSolver(x -> x);
        solver.solve(1.0, 0.0);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testSolve_FunctionThrowsException() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: f.value throws FunctionEvaluationException
        UnivariateRealFunction throwingFunc = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Error"), 0);
        };
        BrentSolver solver = new BrentSolver(throwingFunc);
        solver.solve(-1.0, 1.0);
    }

    @Test(expected = MaxIterationsExceededException.class)
    public void testSolve_MaxIterationsExceeded() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Case: MaxIterationsExceededException
        // We use a function that oscillates wildly to prevent convergence
        BrentSolver solver = new BrentSolver(x -> Math.sin(1/x));
        solver.solve(0.0000001, 1.0);
    }
}
